export const chapters: Chapter[] = units.map(unit => ({
  id: id(unit.id), subjectId, parentId: unit.parent ? id(unit.parent) : undefined,
  number: unit.number, title: unit.title, articleId: id(unit.id),
}));

export const articles: Article[] = units.map(unit => ({
  id: id(unit.id), subjectId, chapterId: id(unit.id), number: unit.number, title: unit.title,
  intro: unit.intro, updatedAt, version: 1,
  sections: [
    ...unit.sections,
    {
      ...section('transferfrage', 'Transferfrage', unit.transfer.question),
      hint: { title: 'Musterantwort', label: 'Selbstkontrolle', content: unit.transfer.answer },
    },
  ],
}));

